-- ============================================================================
-- TRIGGER: Block UPDATE/DELETE on ledgers.current_balance
--          (only allow INSERT via ledger_entries)
-- ============================================================================

CREATE OR REPLACE FUNCTION deny_ledger_balance_direct_update()
RETURNS TRIGGER AS $$
BEGIN
  IF OLD.current_balance IS DISTINCT FROM NEW.current_balance THEN
    RAISE EXCEPTION 'ledger.current_balance cannot be modified directly: use ledger_entries';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_deny_ledger_balance_update
  BEFORE UPDATE ON ledgers
  FOR EACH ROW EXECUTE FUNCTION deny_ledger_balance_direct_update();

