-- ============================================================================
-- FUNCTION: Verify ledger entry hash chain on INSERT
-- ============================================================================

CREATE OR REPLACE FUNCTION verify_ledger_entry_hash_chain()
RETURNS TRIGGER AS $$
DECLARE
  last_hash TEXT;
BEGIN
  -- Find the most recent entry for this ledger
  SELECT entry_hash INTO last_hash
  FROM ledger_entries
  WHERE ledger_id = NEW.ledger_id
  ORDER BY txn_seq DESC
  LIMIT 1;

  -- If there is a prior entry, NEW.prevEntryHash must match it
  IF last_hash IS NOT NULL AND (NEW.prev_entry_hash IS NULL OR NEW.prev_entry_hash != last_hash) THEN
    RAISE EXCEPTION 'Ledger entry hash chain broken: expected prev_entry_hash %, got %', last_hash, NEW.prev_entry_hash;
  END IF;

  -- For the very first entry, prevEntryHash should be NULL
  IF last_hash IS NULL AND NEW.prev_entry_hash IS NOT NULL THEN
    RAISE EXCEPTION 'First ledger entry must have NULL prev_entry_hash';
  END IF;

  -- Verify txnSeq is strictly greater than last entry
  IF last_hash IS NOT NULL THEN
    IF NEW.txn_seq <= (SELECT txn_seq FROM ledger_entries WHERE ledger_id = NEW.ledger_id ORDER BY txn_seq DESC LIMIT 1) THEN
      RAISE EXCEPTION 'txn_seq must be strictly monotonically increasing';
    END IF;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_verify_ledger_hash_chain
  BEFORE INSERT ON ledger_entries
  FOR EACH ROW EXECUTE FUNCTION verify_ledger_entry_hash_chain();

-- ============================================================================
-- INDEXES: Additional performance indexes beyond Prisma-managed ones
-- ============================================================================

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_loan_applications_created
  ON loan_applications (created_at DESC);

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_payments_gateway_ref
  ON payments (gateway_ref);

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_payments_tx_ref
  ON payments (tx_ref);

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_repayment_schedules_due_status
  ON repayment_schedules (due_date, status)
  WHERE status IN ('SCHEDULED', 'PAST_DUE', 'DEFAULTED');

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_notifications_pending
  ON notifications (status, created_at)
  WHERE status IN ('QUEUED', 'PENDING');

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_audit_logs_created_actor
  ON audit_logs (created_at DESC, changed_by_id);

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_sessions_expiry_active
  ON sessions (expires_at, status)
  WHERE status = 'ACTIVE';
